function ProfileMenu({ theme, onClose, onToggleTheme, onViewProfile, onChangePassword, onLogout }) { return <><div className="profile-menu-backdrop" onClick={onClose} /><aside className="profile-menu" role="menu" onClick={event => event.stopPropagation()}><div className="profile-menu-header"><div className="profile-menu-avatar">MA</div><div><strong>Maria A.</strong><span className="role-badge">System Administrator</span><small>admin@elingap.gov.ph</small></div></div><div className="profile-details"><div><small>Assigned Office</small><strong>OSCA Santa Maria Municipal Hall</strong></div><div><small>Last Active / Login</small><strong>Sep 14, 2024 · 07:48 AM</strong></div><div className="account-status"><small>Account Status</small><span><i /> Active</span></div></div><div className="profile-actions"><button onClick={onViewProfile}><UserCog size={16} /><span>View Full Profile &amp; Activity</span><ChevronRight size={15} /></button><button onClick={onChangePassword}><ShieldCheck size={16} /><span>Change Password</span><ChevronRight size={15} /></button><button onClick={onToggleTheme}><span className="profile-action-icon">{theme === 'light' ? <Moon size={16} /> : <Sun size={16} />}</span><span>System Preferences</span><small>{theme === 'light' ? 'Light mode' : 'Dark mode'}</small></button></div><button className="profile-logout" onClick={onLogout}><LogOut size={16} /> Log Out</button></aside></>; }
function ProfileDetailsModal({ onClose }) { return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="profile-modal-title"><div className="modal-card profile-details-modal"><div className="modal-heading"><div><h2 id="profile-modal-title">Maria A.</h2><p>System Administrator · admin@elingap.gov.ph</p></div><button className="icon-button" onClick={onClose} aria-label="Close profile"><X size={19} /></button></div><div className="profile-modal-grid"><div><small>Assigned Office</small><strong>OSCA Santa Maria Municipal Hall</strong></div><div><small>Account Status</small><strong className="health-value"><i /> Active</strong></div><div><small>Last Active / Login</small><strong>Sep 14, 2024 · 07:48 AM</strong></div><div><small>Recent Activity</small><strong>18 actions this month</strong></div></div><div className="modal-actions"><button className="primary-button" onClick={onClose}>Done</button></div></div></div>; }
function ChangePasswordModal({ onClose, onSaved }) { const [values, setValues] = useState({ current: '', next: '', confirm: '' }); const [error, setError] = useState(''); const update = (key, value) => { setValues(current => ({ ...current, [key]: value })); setError(''); }; const save = () => { if (!values.current || !values.next || !values.confirm) return setError('Complete all password fields.'); if (values.next.length < 8) return setError('New password must be at least 8 characters.'); if (values.next !== values.confirm) return setError('New password and confirmation do not match.'); onSaved(); }; return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="password-modal-title"><div className="modal-card password-modal"><div className="modal-heading"><div><h2 id="password-modal-title">Change Password</h2><p>Update the password for admin@elingap.gov.ph.</p></div><button className="icon-button" onClick={onClose} aria-label="Close password dialog"><X size={19} /></button></div><label className="field-label">Current password<input type="password" value={values.current} onChange={event => update('current', event.target.value)} /></label><label className="field-label">New password<input type="password" value={values.next} onChange={event => update('next', event.target.value)} /></label><label className="field-label">Confirm password<input type="password" value={values.confirm} onChange={event => update('confirm', event.target.value)} /></label>{error && <p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" onClick={save}><Check size={16} /> Update password</button></div></div></div>; }
function LogoutConfirmModal({ onCancel, onConfirm }) { return <div className="modal-backdrop logout-modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="logout-modal-title"><div className="modal-card logout-modal"><div className="logout-icon"><LogOut size={20} /></div><h2 id="logout-modal-title">Are you sure you want to log out?</h2><p>You will be returned to the public eLINGAP landing page.</p><div className="modal-actions"><button className="secondary-button" onClick={onCancel}>Cancel</button><button className="danger-button" onClick={onConfirm}><LogOut size={16} /> Log Out</button></div></div></div>; }
function ExportProgressModal({ type, onClose, onComplete }) { const [progress, setProgress] = useState(0); React.useEffect(() => { const timer = window.setInterval(() => setProgress(value => { const next = Math.min(value + 20, 100); if (next === 100) { window.clearInterval(timer); window.setTimeout(() => { const url = URL.createObjectURL(new Blob(['eLINGAP export\nGenerated,Data\nComplete,Yes'], { type: 'text/csv;charset=utf-8;' })); const link = document.createElement('a'); link.href = url; link.download = `elingap-${type}-export.csv`; link.click(); URL.revokeObjectURL(url); onComplete(); }, 250); } return next; }), 180); return () => window.clearInterval(timer); }, [type, onComplete]); return <div className="modal-backdrop" role="dialog" aria-modal="true"><div className="export-modal modal-card"><div className="export-icon"><Download size={20} /></div><h2>Preparing CSV export</h2><p>Your {type === 'registry' ? 'senior registry' : 'system logs'} export is being prepared.</p><div className="export-progress-track"><i style={{ width: `${progress}%` }} /></div><div className="export-progress-meta"><span>{progress < 100 ? 'Collecting records...' : 'Download ready'}</span><strong>{progress}%</strong></div><button className="secondary-button" onClick={onClose}>Cancel</button></div></div>; }
function TemplatePrompt({ template, onClose, onApply }) { const variables = [...template.text.matchAll(/\[([A-Z]+)\]/g)].map(match => match[1]); const [values, setValues] = useState(() => Object.fromEntries(variables.map(variable => [variable, '']))); const apply = () => { if (variables.some(variable => !values[variable].trim())) return; onApply(template.text.replace(/\[([A-Z]+)\]/g, (_, variable) => values[variable])); }; return <div className="modal-backdrop" role="dialog" aria-modal="true"><div className="modal-card template-prompt-modal"><div className="modal-heading"><div><h2>Complete message details</h2><p>{template.name} needs a few details before it is added.</p></div><button className="icon-button" onClick={onClose} aria-label="Close template prompt"><X size={19} /></button></div><div className="template-variable-fields">{variables.map(variable => <label className="field-label" key={variable}>{variable === 'DATE' ? 'Date' : 'Barangay'}<input type={variable === 'DATE' ? 'date' : 'text'} value={values[variable]} onChange={event => setValues(current => ({ ...current, [variable]: event.target.value }))} placeholder={variable === 'DATE' ? 'Choose a date' : 'Enter barangay'} /></label>)}</div><div className="modal-actions"><button className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" onClick={apply}><Check size={16} /> Use template</button></div></div></div>; }
function HelpPage({ setToast }) { const [openFaq, setOpenFaq] = useState(null); const guides = [{ icon: ClipboardList, title: 'Senior Registration Guide', description: 'Step-by-step process for adding and verifying senior records.' }, { icon: HeartPulse, title: 'Benefits Disbursement Process', description: 'Quarterly pension handling and approval checkpoints.' }, { icon: MessageSquare, title: 'SMS Broadcast Manual', description: 'Message templates, targeting, scheduling, and delivery checks.' }, { icon: ShieldCheck, title: 'ID Renewal Workflow', description: 'Document requirements and validation procedures.' }, { icon: UserCog, title: 'System Admin Manual', description: 'User management, roles, permissions, and access reviews.' }, { icon: Archive, title: 'Data Privacy & Security', description: 'Policies and safeguards under Republic Act 10173.' }]; const faqs = [{ question: 'How do I register a senior citizen?', answer: 'Open Senior Records Registry, select Add New Senior, complete the required identity and barangay fields, then submit the record for validation.' }, { question: 'How do I send an SMS broadcast?', answer: 'Open SMS Dispatcher, choose the target barangay, select a quick template or write a message, review the recipient estimate, and schedule the broadcast.' }, { question: 'What happens when an OSCA ID expires?', answer: 'The record appears in the validation queue. Review the renewal documents, update the expiration date, and mark the record as verified.' }, { question: 'How do I approve benefits?', answer: 'Open Benefits & Programs, select the current cycle, review eligible records, and confirm the approved payout batch.' }, { question: 'How do I suspend a user?', answer: 'Open User Accounts and use the Suspend action on the account row. The user immediately loses active access until reactivated.' }, { question: 'Can I export the masterlist?', answer: 'Yes. Open Senior Records Registry and select Export CSV. The current filtered registry view is downloaded for review.' }]; const guideDownload = title => { setToast(`${title} PDF download started.`); setTimeout(() => setToast(''), 3000); }; return <><section className="page-intro"><div><p className="section-kicker">Support center</p><h2>Help &amp; Support</h2><p className="section-subtitle">Documentation, FAQs, and system support resources for eLINGAP administrators.</p></div></section><section className="support-banner"><div><span className="support-kicker">Need immediate assistance?</span><h3>Contact OSCA IT Support</h3><p>Monday–Friday, 8:00 AM–5:00 PM</p></div><div className="support-actions"><a className="support-button light" href="tel:+63448151234"><PhoneIcon /> (044) 815-1234</a><a className="support-button" href="mailto:it.support@elingap.gov.ph"><MailIcon /> Email Support</a></div></section><section className="support-section"><div className="support-section-heading"><div><h3>Quick Reference Guides</h3><p>Download operational guides for common administrator workflows.</p></div><FileText size={19} /></div><div className="guide-grid">{guides.map(({ icon: Icon, title, description }) => <article className="guide-card" key={title}><span className="guide-icon"><Icon size={19} /></span><h4>{title}</h4><p>{description}</p><button className="download-link" onClick={() => guideDownload(title)}>Download PDF <span>→</span></button></article>)}</div></section><section className="support-section faq-section"><div className="support-section-heading"><div><h3>Frequently Asked Questions</h3><p>Answers to common administration questions.</p></div><CircleHelp size={19} /></div><div className="faq-list">{faqs.map((faq, index) => <div className={`faq-item ${openFaq === index ? 'is-open' : ''}`} key={faq.question}><button onClick={() => setOpenFaq(openFaq === index ? null : index)}><span>{faq.question}</span><ChevronDown size={17} /></button>{openFaq === index && <p>{faq.answer}</p>}</div>)}</div></section><section className="system-info-card"><div className="system-info-title"><Gauge size={19} /><div><h3>System Information</h3><p>Environment and service health details</p></div></div><div className="system-info-grid"><div><small>Application version</small><strong>eLINGAP v2.4.1</strong></div><div><small>Municipality</small><strong>Santa Maria, Bulacan</strong></div><div><small>Database health</small><strong className="health-value"><i /> Healthy - 98.2% uptime</strong></div><div><small>Last updated</small><strong>Sep 14, 2024</strong></div></div></section></>; }
function PhoneIcon() { return <span className="support-symbol">☎</span>; }
function MailIcon() { return <span className="support-symbol">✉</span>; }

function Modal({ type, editUser, onClose, onSave }) { const titles = { senior: ['Add New Senior', 'Create a new senior citizen registry record.'], program: ['Create Program', 'Set up a new benefits and programs cycle.'], user: [editUser ? 'Edit User' : 'Add User', editUser ? 'Update role, email, or account details.' : 'Invite a staff member to the eLINGAP workspace.'] }; const [title, subtitle] = titles[type]; const [form, setForm] = useState(type === 'senior' ? { name: '', age: '', barangay: 'Poblacion' } : type === 'program' ? { name: '', agency: '', budget: '', cycle: 'Q4 2026' } : { name: editUser?.name || '', email: editUser?.email || '', role: editUser?.role || 'OSCA Staff' }); const update = (key, value) => setForm(current => ({ ...current, [key]: value })); const save = () => { if (Object.values(form).some(value => !String(value).trim())) return; if (type === 'senior') onSave({ type, label: 'Senior record', id: `SC-2026-${Math.floor(10000 + Math.random() * 89999)}`, name: form.name, age: form.age, barangay: form.barangay }); if (type === 'program') onSave({ type, label: 'Program', program: { name: form.name, agency: form.agency, budget: form.budget, used: 0, cycle: form.cycle } }); if (type === 'user') onSave({ type, label: 'User account', editEmail: editUser?.email, user: { ...editUser, name: form.name, email: form.email, role: form.role, status: editUser?.status || 'Active' } }); }; return <div className="modal-backdrop" role="dialog" aria-modal="true"><div className="modal-card"><div className="modal-heading"><div><h2>{title}</h2><p>{subtitle}</p></div><button className="icon-button" onClick={onClose} aria-label="Close dialog"><X size={19} /></button></div><div className="modal-form">{type === 'senior' && <><label className="field-label">Full name<input value={form.name} onChange={event => update('name', event.target.value)} placeholder="Enter full name" /></label><label className="field-label">Age<input type="number" min="60" value={form.age} onChange={event => update('age', event.target.value)} placeholder="60" /></label><label className="field-label">Barangay<select value={form.barangay} onChange={event => update('barangay', event.target.value)}><option>Poblacion</option><option>Sta. Cruz</option><option>Kaybanban</option><option>San Gabriel</option></select></label></>}{type === 'program' && <><label className="field-label">Program name<input value={form.name} onChange={event => update('name', event.target.value)} placeholder="Enter program name" /></label><label className="field-label">Implementing agency<input value={form.agency} onChange={event => update('agency', event.target.value)} placeholder="Enter agency" /></label><label className="field-label">Budget allocation<input value={form.budget} onChange={event => update('budget', event.target.value)} placeholder="₱0" /></label><label className="field-label">Cycle<select value={form.cycle} onChange={event => update('cycle', event.target.value)}><option>Q4 2026</option><option>Annual 2027</option></select></label></>}{type === 'user' && <><label className="field-label">Full name<input value={form.name} onChange={event => update('name', event.target.value)} placeholder="Enter full name" /></label><label className="field-label">Email address<input type="email" value={form.email} onChange={event => update('email', event.target.value)} placeholder="name@osca.gov.ph" /></label><label className="field-label">Role<select value={form.role} onChange={event => update('role', event.target.value)}><option>OSCA Staff</option><option>Barangay Coordinator</option><option>System Administrator</option></select></label></>}</div><div className="modal-actions"><button className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" onClick={save}><Check size={16} /> {editUser ? 'Save changes' : `Save ${type === 'program' ? 'program' : type === 'user' ? 'user' : 'record'}`}</button></div></div></div>; }

if (document.getElementById('admin-dashboard-root')) createRoot(document.getElementById('admin-dashboard-root')).render(<App />);
